function validate(input) {
  const [fn, args] = input;
  const names = ['add', 'tax', 'increment', 'sum', 'countArgs', 'greet', 'pick'];
  if (!names.includes(fn)) return `fn must be one of ${names.join(', ')}.`;
  if (!Array.isArray(args) || args.length < 1 || args.length > 100) return 'args must hold 1 to 100 values.';
  const [context, ...rest] = args;
  if (context === null || typeof context !== 'object' || Array.isArray(context)) return 'args[0] must be a JSON object.';
  const size = JSON.stringify(context).length;
  if (size < 2 || size > 100000) return 'args[0] must be 2 to 100,000 characters of JSON.';
  const number = value => typeof value === 'number';
  const string = value => typeof value === 'string';
  const shape = (key, test, count, each) => test(context[key]) && rest.length === count && rest.every(each);
  if (fn === 'add' && !shape('a', number, 1, number)) return 'add needs a number "a" in the context and one number.';
  if (fn === 'tax' && !shape('item', string, 2, number)) return 'tax needs a string "item" in the context and two numbers.';
  if (fn === 'increment' && !shape('count', number, 0, number)) return 'increment needs a number "count" in the context and no other arguments.';
  if (fn === 'sum' && !shape('base', number, rest.length, number)) return 'sum needs a number "base" in the context, then only numbers.';
  if (fn === 'greet' && !shape('name', string, 2, string)) return 'greet needs a string "name" in the context and two strings.';
  if (fn === 'pick' && !(rest.length === 1 && string(rest[0]))) return 'pick takes one string, the key to read.';
  return null;
}

