function adapt(input, solve, kit) {
  const [name, args] = input, [context, ...rest] = args;
  const show = value => { try { return JSON.stringify(value) ?? String(value); } catch { return String(value); } };
  const ran = (self, values) => kit.trace(`${name} runs with this = ${show(self)} and arguments ${show(values)}`);
  // The functions a case can name. Each one reports the this and the arguments it received.
  const library = {
    add: function add(b) { ran(this, [b]); return this.a + b; },
    tax: function tax(price, taxRate) { ran(this, [price, taxRate]); return `The cost of the ${this.item} is ${price * taxRate}`; },
    increment: function increment() { ran(this, []); this.count++; return this.count; },
    sum: function sum(...nums) { ran(this, nums); return nums.reduce((total, x) => total + x, this.base); },
    countArgs: function countArgs(...values) { ran(this, values); return values.length; },
    greet: function greet(greeting, mark) { ran(this, [greeting, mark]); return `${greeting}, ${this.name}${mark}`; },
    pick: function pick(key) { ran(this, [key]); return Object.hasOwn(this, key) ? this[key] : null; },
  };
  const fn = library[name];
  if (typeof fn.callPolyfill !== 'function') throw new Error('Functions have no callPolyfill method yet: assign a function to Function.prototype.callPolyfill.');
  kit.trace(`${name}.callPolyfill(${args.map(show).join(', ')}) is called`);
  const call = Function.prototype.call;
  Function.prototype.call = function () { throw new Error('Solve it without Function.prototype.call.'); };
  let result;
  try {
    result = fn.callPolyfill(context, ...rest);
  } finally {
    Function.prototype.call = call;
  }
  if (result === undefined) throw new Error('callPolyfill returned undefined; return what the function returns.');
  kit.trace(`callPolyfill returns ${show(result)}`);
  return result;
}

