function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const words = ['salad', 'burger', 'tea', 'Ada', 'Lin', 'x', ''];
  const primitive = () => {
    const roll = rand();
    if (roll < 0.4) return int(-50, 50);
    if (roll < 0.7) return pick(words);
    if (roll < 0.85) return rand() < 0.5;
    return null;
  };
  // Unrelated keys in the context, which the function must still see.
  const context = {};
  const extra = small ? int(0, 2) : 300;
  for (let i = 0; i < extra; i++) context[pick(['k', 'id', 'v', 'tag']) + i] = rand() < 0.2 ? [primitive(), { inner: primitive() }] : primitive();
  const name = pick(['add', 'tax', 'increment', 'sum', 'countArgs', 'greet', 'pick']);
  let rest;
  if (name === 'add') {
    context.a = int(-100, 100);
    rest = [int(-100, 100)];
  } else if (name === 'tax') {
    context.item = pick(words);
    rest = [int(0, 200), pick([0, 0.5, 1, 1.25, 1.5, 2])];
  } else if (name === 'increment') {
    context.count = int(-10, 100);
    rest = [];
  } else if (name === 'sum') {
    context.base = int(-50, 50);
    rest = Array.from({ length: small ? int(0, 4) : 99 }, () => int(-1000, 1000));
  } else if (name === 'countArgs') {
    rest = Array.from({ length: small ? int(0, 4) : 99 }, primitive);
  } else if (name === 'greet') {
    context.name = pick(words);
    rest = [pick(['Hello', 'Hi', 'Hey']), pick(['!', '.', '?', ''])];
  } else {
    const keys = Object.keys(context);
    rest = [keys.length && rand() < 0.7 ? pick(keys) : pick(['missing', 'a', 'name'])];
  }
  return [name, [context, ...rest]];
}
